using ProductService.Api.Models;

namespace ProductService.Api.Repositories;

/// <summary>
/// Data access for product.Products. Only active products (IsActive = 1) are read, updated or deleted.
/// </summary>
public interface IProductRepository
{
    Task<IReadOnlyList<Product>> GetAllAsync(CancellationToken cancellationToken = default);

    Task<Product?> GetByIdAsync(int id, CancellationToken cancellationToken = default);

    /// <returns>The Id generated by the database.</returns>
    Task<int> CreateAsync(Product product, CancellationToken cancellationToken = default);

    /// <returns>False when no active product has this Id.</returns>
    Task<bool> UpdateAsync(Product product, CancellationToken cancellationToken = default);

    /// <summary>Soft delete: sets IsActive = 0 instead of removing the row.</summary>
    /// <returns>False when no active product has this Id.</returns>
    Task<bool> DeleteAsync(int id, CancellationToken cancellationToken = default);
}
